    /**
     * Loads data for the mail merge.
     *
     * @param data - Mail merge data. The first element of the array is the array with names of the merge fields.
     *   The rest of the array elements are arrays with values for the merge fields.
     *
     * @example
     * ```js
     * let doc = Api.GetDocument();
     * let paragraph = doc.GetElement(0);
     * let fields = ["Greeting line", "First name", "Last name"];
     * for (let i = 0; i < fields.length; ++i)
     * {
     * 	let run = Api.CreateRun();
     * 	run.AddText(fields[i]);
     * 	paragraph.AddElement(run);
     * 	run.WrapInMailMergeField();
     * 	paragraph.AddText(" ");
     * }
     * paragraph.AddText("!");
     * Api.LoadMailMergeData([fields, ["Dear", "John", "Smith"], ["Hello", "Lara", "Davis"]]);
     * Api.MailMerge();
     * ```
     *
     * @see https://api.onlyoffice.com/docs/office-api/usage-api/document-api/Api/Methods/LoadMailMergeData/
     */
    LoadMailMergeData(data: string[][]): boolean;

    /**
     * Starts the mail merge process.
     *
     * @param startIndex - The start index of the document for mail merge process.
     * @param endIndex - The end index of the document for mail merge process.
     *
     * @example
     * ```js
     * let doc = Api.GetDocument();
     * let paragraph = doc.GetElement(0);
     * let fields = ["Greeting line", "First name", "Last name"];
     * for (let i = 0; i < fields.length; ++i)
     * {
     * 	let run = Api.CreateRun();
     * 	run.AddText(fields[i]);
     * 	paragraph.AddElement(run);
     * 	run.WrapInMailMergeField();
     * 	paragraph.AddText(" ");
     * }
     * paragraph.AddText("!");
     * Api.LoadMailMergeData([fields, ["Dear", "John", "Smith"], ["Hello", "Lara", "Davis"]]);
     * Api.MailMerge(1);
     * ```
     *
     * @see https://api.onlyoffice.com/docs/office-api/usage-api/document-api/Api/Methods/MailMerge/
     */
