  /** Class representing gradient stop. */
  export interface ApiGradientStop {
    /**
     * Returns a type of the ApiGradientStop class.
     *
     * @example
     * ```js
     * let worksheet = Api.GetActiveSheet();
     * let gradientStop1 = Api.CreateGradientStop(Api.CreateRGBColor(255, 213, 191), 0);
     * let gradientStop2 = Api.CreateGradientStop(Api.CreateRGBColor(255, 111, 61), 100000);
     * let fill = Api.CreateLinearGradientFill([gradientStop1, gradientStop2], 5400000);
     * let stroke = Api.CreateStroke(0, Api.CreateNoFill());
     * worksheet.AddShape("flowChartOnlineStorage", 60 * 36000, 35 * 36000, fill, stroke, 0, 2 * 36000, 1, 3 * 36000);
     * let classType = gradientStop1.GetClassType();
     * worksheet.SetColumnWidth(0, 15);
     * worksheet.SetColumnWidth(1, 10);
     * worksheet.GetRange("A1").SetValue("Class Type = " + classType);
     * ```
     *
     * @see https://api.onlyoffice.com/docs/office-api/usage-api/spreadsheet-api/ApiGradientStop/Methods/GetClassType/
     */
    GetClassType(): "gradientStop";
  }

  /** Class representing a group of drawings. */
  export interface ApiGroup extends Omit<ApiDrawing, "GetClassType"> {
    /**
     * Returns a type of the ApiGroup class.
     *
     * @example
     * ```js
     * let worksheet = Api.GetActiveSheet();
     * let fill1 = Api.CreateSolidFill(Api.CreateRGBColor(255, 111, 61));
     * let fill2 = Api.CreateSolidFill(Api.CreateRGBColor(51, 51, 51));
     * let stroke = Api.CreateStroke(0, Api.CreateNoFill());
     * let shape1 = worksheet.AddShape("flowChartOnlineStorage", 60 * 36000, 35 * 36000, fill1, stroke, 0, 2 * 36000, 0, 3 * 36000);
     * let shape2 = worksheet.AddShape("flowChartOnlineStorage", 60 * 36000, 35 * 36000, fill2, stroke, 0, 15 * 36000, 0, 30 * 36000);
     *
     * let group = worksheet.GroupDrawings([shape1, shape2]);
     * let classType = group.GetClassType();
     *
     * let content1 = shape1.GetDocContent();
     * let paragraph1 = content1.GetElement(0);
     * paragraph1.AddText("Class Type = " + classType);
     *
     * let content2 = shape2.GetDocContent();
     * let paragraph2 = content2.GetElement(0);
     * paragraph2.AddText("Class Type = " + classType);
     * ```
     *
     * @see https://api.onlyoffice.com/docs/office-api/usage-api/spreadsheet-api/ApiGroup/Methods/GetClassType/
     */
    GetClassType(): "group";

    /**
     * Returns the parent sheet of the current drawing.
     *
     * @since 8.3.0
     */
    GetParentSheet(): ApiWorksheet;

    /**
     * Ungroups the current group of drawings.
     *
     * @returns The array of the ungrouped objects, or null if the group is not in the document, cannot be
     *   ungrouped, or when called in the document builder.
     * @since 9.5.0
     *
     * @example
     * ```js
     * let worksheet = Api.GetActiveSheet();
     * let fill1 = Api.CreateSolidFill(Api.CreateRGBColor(255, 111, 61));
     * let fill2 = Api.CreateSolidFill(Api.CreateRGBColor(51, 51, 51));
     * let stroke = Api.CreateStroke(0, Api.CreateNoFill());
     * let shape1 = worksheet.AddShape("flowChartOnlineStorage", 60 * 36000, 35 * 36000, fill1, stroke, 0, 2 * 36000, 0, 3 * 36000);
     * let shape2 = worksheet.AddShape("flowChartOnlineStorage", 60 * 36000, 35 * 36000, fill2, stroke, 0, 15 * 36000, 0, 30 * 36000);
     *
     * let group = worksheet.GroupDrawings([shape1, shape2]);
     * group.Ungroup();
     *
     * let content1 = shape1.GetDocContent();
     * let paragraph1 = content1.GetElement(0);
     * paragraph1.AddText("Shapes are ungrouped");
     *
     * let content2 = shape2.GetDocContent();
     * let paragraph2 = content2.GetElement(0);
     * paragraph2.AddText("Shapes are ungrouped");
     * ```
     *
     * @see https://api.onlyoffice.com/docs/office-api/usage-api/spreadsheet-api/ApiGroup/Methods/Ungroup/
     */
    Ungroup(): ApiDrawing[] | null;
  }

